// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 100 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(uint256 value, bytes32 hash, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(value <= 1000 ether);
        vm.assume(actor != address(c));

        uint256 balanceBefore = address(c).balance;
        vm.deal(actor, value);
        vm.prank(actor);
        bool ok = false;
        try c.lockInGuess{value: value}(hash) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertEq(address(c).balance, balanceBefore + 1 ether, "Balance must increase by 1 ether on success");
        } else {
            assertEq(address(c).balance, balanceBefore, "Balance must remain unchanged on failure");
        }
    }
}
